entries[91802] = { ["name"] = "Jade Pandaren Kite String", ["text"] = "Binds when picked up\nUnique\nMount\nRequires Level 70\nRequires Artisan Riding\nUse: Teaches you how to summon this mount. This is a flying mount.\nSell Price:" }
entries[91803] = { ["name"] = "Snap Root Tuber", ["text"] = "Binds when picked up\nRequires Level 85\nUse: Increases haste by 4000 for 25 sec. (1 Min Cooldown)\nSell Price:" }
entries[91806] = { ["name"] = "Unstable Portal Shard", ["text"] = "Binds when picked up\nUse: \"Plant\" the Unstable Portal Shard.\n\"Chaotic arcane energy crystallized from high-traffic portals. The soil of Sunsong Ranch will stabilize this energy, yielding a shard that can be broken on the farm to open a one-shot portal to a major city.\"\nSell Price:" }
entries[91807] = { ["name"] = "Head of Or", ["text"] = "Quest Item\n\"The confusion of defeat is frozen on this disembodied right head of Or.\"" }
entries[91808] = { ["name"] = "Head of Dac", ["text"] = "Quest Item\n\"Dac's tongue still protrudes from his face in a final act of defiance at being defeated.\"" }
entries[91809] = { ["name"] = "Head of Ruk'ra", ["text"] = "Quest Item\n\"A look of signature Kor'kron pride and defiance is forever emblazened on this orc's head.\"" }
entries[91810] = { ["name"] = "Head of Snicklefritz", ["text"] = "Quest Item\n\"The gas mask is still stuck on this head.\"" }
entries[91814] = { ["name"] = "Pristine Golden Crownfeather", ["text"] = "Quest Item\n\"An immaculately clean, crisp, quill from a Child of Chi-Ji.\"" }
