entries[91877] = { ["name"] = "Domination Point Commission", ["text"] = "Binds when picked up\n\"A small token, featuring writing in the Horde language, and a map of Pandaria with red ink splashed on it. Bring it to Proveditor Grantley at Lion's Landing.\"" }
entries[91902] = { ["name"] = "Universal Remote", ["text"] = "Quest Item\nUnique\nUse: Operating on frequency 329-er. (5 Sec Cooldown)\n\"Avoid contact with eyes. Safety not guaranteed.\"" }
entries[91904] = { ["name"] = "Stackable Stag", ["text"] = "Binds when picked up\nToy\nUse: Summon a Stackable Stag at the target location. If there is another Stackable Stag nearby, your Stackable Stag will stack on top of it. (1 Min Cooldown)\nSell Price:" }
