entries[92049] = { ["name"] = "Mercenary Contract: Mage", ["text"] = "Use: Hire a mage that casts Arcane Brilliance on nearby Horde players, free of charge.\n\nArcane Brilliance\n30 yd range\nInstant\nRequires Mage Infuses the target with brilliance, increasing their spell power by 10% and their critical strike chance by 5% for 1 hour. Only works in Krasarang Wilds." }
entries[92050] = { ["name"] = "Mercenary Contract: Paladin", ["text"] = "Use: Hire a paladin that casts Blessing of Might on nearby Horde players, free of charge.\n\nBlessing of Might\n30 yd range\nInstant\nRequires Paladin Places a Blessing on the friendly target, increasing mastery by 3000. Only works in Krasarang Wilds." }
entries[92051] = { ["name"] = "Mercenary Contract: Priest", ["text"] = "Use: Hire a priest that casts Power Word: Fortitude on nearby Horde players, free of charge.\n\nPower Word: Fortitude 4.4% of base mana 40 yd range Instant\nRequires Priest\nRequires level 22 Infuses the target with vitality, increasing Stamina by 10% for 1 hour. Only works in Krasarang Wilds." }
entries[92052] = { ["name"] = "Mercenary Contract: Druid", ["text"] = "Use: Hire a druid that casts Mark of the Wild on nearby Horde players, free of charge.\n\nMark of the Wild\n30 yd range\nInstant\nRequires Druid Increases the friendly target's Strength, Agility, and Intellect by 5% for 1 hour. Only works in Krasarang Wilds." }
entries[92053] = { ["name"] = "Mercenary Contract: Warrior", ["text"] = "Use: Hire a warrior that casts Echoing Battle Shout on nearby Horde players, free of charge.\n\nEchoing Battle Shout\n30 yd range\nInstant\nRequires Warrior Increases the target's attack power by 10%. Only works in Krasarang Wilds." }
entries[92054] = { ["name"] = "Mercenary Contract: Rogue", ["text"] = "Use: Hire a rogue that casts Swiftblade's Nod on nearby Horde players, free of charge.\n\nSwiftblade's Nod\n30 yd range\nInstant\nRequires Rogue Increases the target's melee and ranged attack speed by 10%. Only works in Krasarang Wilds." }
entries[92055] = { ["name"] = "Mercenary Contract: Shaman", ["text"] = "Use: Hire a shaman that casts Binding Elemental Oath on nearby Horde players, free of charge.\n\nBinding Elemental Oath\n30 yd range\nInstant\nRequires Shaman\nRequires level 55 Grants the target 5% spell haste. Only works in Krasarang Wilds." }
