entries[92426] = { ["name"] = "Sealed Tome of the Lost Legion", ["text"] = "Unique\nRequires Level 90\nUse: Combine with a Healthstone to bind the tome to yourself.\n\"The book seems unusually normal, aside from the chains and socket binding it.\"" }
entries[92427] = { ["name"] = "Guard Contract: Tower", ["text"] = "Use: Hire guards to protect a capturable tower in Krasarang Wilds. You must be near the tower, and your faction must control it." }
entries[92428] = { ["name"] = "Guard Contract: Graveyard", ["text"] = "Use: Hire guards to protect a capturable graveyard in Krasarang Wilds. You must be near the graveyard, and your faction must control it." }
entries[92429] = { ["name"] = "Lion's Landing Banquet", ["text"] = "Use: Lay out a banquet for Alliance players in Lion's Landing. Lasts 20 minutes." }
entries[92430] = { ["name"] = "Portal Reagents: Shrine of Seven Stars", ["text"] = "Use: Enough fuel to power a one-way portal to the Shrine of Seven Stars for 20 minutes." }
entries[92431] = { ["name"] = "Portal Reagents: Stormwind", ["text"] = "Use: Enough fuel to power a one-way portal to Stormwind for 20 minutes." }
entries[92432] = { ["name"] = "Portal Reagents: Skyfire", ["text"] = "Use: Enough fuel to power a bi-directional portal to the Skyfire for 20 minutes." }
entries[92433] = { ["name"] = "Mercenary Contract: Shaman", ["text"] = "Use: Hire a shaman that casts Binding Elemental Oath on nearby Alliance players, free of charge.\n\nBinding Elemental Oath\n30 yd range\nInstant\nRequires Shaman\nRequires level 55 Grants the target 5% spell haste. Only works in Krasarang Wilds." }
entries[92434] = { ["name"] = "Mercenary Contract: Rogue", ["text"] = "Use: Hire a rogue that casts Swiftblade's Nod on nearby Alliance players, free of charge.\n\nSwiftblade's Nod\n30 yd range\nInstant\nRequires Rogue Increases the target's melee and ranged attack speed by 10%. Only works in Krasarang Wilds." }
entries[92435] = { ["name"] = "Mercenary Contract: Warrior", ["text"] = "Use: Hire a warrior that casts Echoing Battle Shout on nearby Alliance players, free of charge.\n\nEchoing Battle Shout\n30 yd range\nInstant\nRequires Warrior Increases the target's attack power by 10%. Only works in Krasarang Wilds." }
entries[92436] = { ["name"] = "Mercenary Contract: Druid", ["text"] = "Use: Hire a druid that casts Mark of the Wild on nearby Alliance players, free of charge.\n\nMark of the Wild\n30 yd range\nInstant\nRequires Druid Increases the friendly target's Strength, Agility, and Intellect by 5% for 1 hour. Only works in Krasarang Wilds." }
entries[92437] = { ["name"] = "Mercenary Contract: Priest", ["text"] = "Use: Hire a priest that casts Power Word: Fortitude on nearby Alliance players, free of charge.\n\nPower Word: Fortitude 4.4% of base mana 40 yd range Instant\nRequires Priest\nRequires level 22 Infuses the target with vitality, increasing Stamina by 10% for 1 hour. Only works in Krasarang Wilds." }
entries[92438] = { ["name"] = "Mercenary Contract: Paladin", ["text"] = "Use: Hire a paladin that casts Blessing of Might on nearby Alliance players, free of charge.\n\nBlessing of Might\n30 yd range\nInstant\nRequires Paladin Places a Blessing on the friendly target, increasing mastery by 3000. Only works in Krasarang Wilds." }
entries[92439] = { ["name"] = "Mercenary Contract: Mage", ["text"] = "Use: Hire a mage that casts Arcane Brilliance on nearby Alliance players, free of charge.\n\nArcane Brilliance\n30 yd range\nInstant\nRequires Mage Infuses the target with brilliance, increasing their spell power by 10% and their critical strike chance by 5% for 1 hour. Only works in Krasarang Wilds." }
entries[92440] = { ["name"] = "Reliquary Facsimile", ["text"] = "\"A rubbing of the Ancient Korune Tablet. The inscription describes the origin of the Divine Bell.\"\n<Right Click to Read>" }
entries[92441] = { ["name"] = "The Codex of Xerrath", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 90\n\"As you hold the book, whispers of horrifying mysteries tantalize your ears...\"" }
entries[92442] = { ["name"] = "Horde Banner", ["text"] = "Unique (20)\nUse: Place a Horde Banner on the ground. The banner lasts for 10 minutes, and you can have up to 5 banners placed at any time.\n\nYou must be flagged for PvP to place a banner. PvP-flagged Alliance players can attempt to burn your banners." }
entries[92443] = { ["name"] = "Alliance Banner", ["text"] = "Unique (20)\nUse: Place an Alliance Banner on the ground. The banner lasts for 10 minutes, and you can have up to 5 banners placed at any time.\n\nYou must be flagged for PvP to place a banner. PvP-flagged Horde players can attempt to burn your banners." }
entries[92444] = { ["name"] = "Meaty Haunch", ["text"] = "A Little Patience\nUnique (5)\nUse: Provides accessible food for all laborers, increasing labor rate by 60% of base for 60 seconds. (Up to 3 stacks)" }
entries[92470] = { ["name"] = "Snake Oil", ["text"] = "A Little Patience\nUnique (5)\nUse: Provides Snake Oil for gnomish laborers, increasing labor rate by 50% of base for 60 seconds. (Up to 3 stacks) (1 Sec Cooldown)" }
