entries[92727] = { ["name"] = "Glyph of Discreet Magic", ["text"] = "Minor Glyph\nClasses: Mage\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Nether Tempest, Living Bomb, Frost Bomb, Arcane Barrage, and Inferno Blast no longer affect targets more than 5 yds away from their primary target.\nSell Price:" }
entries[92735] = { ["name"] = "Meng-do's Essence", ["text"] = "Quest Item\n\"Incredibly heavy and hot to the touch.\"" }
entries[92736] = { ["name"] = "Gen-Li's Essence", ["text"] = "Quest Item\n\"These motes of dust move unpredictably, floating around your hands as you move them.\"" }
entries[92738] = { ["name"] = "Safari Hat", ["text"] = "Binds to account\nToy\nRequires Battle Pet Training\nUse: Battle pet experience gained is increased by 10%. (3 Sec Cooldown)\n\"Happy hunting!\"\nSell Price:" }
entries[92739] = { ["name"] = "Misplaced Keg", ["text"] = "A Little Patience\nUnique (5)\nUse: A little 'lubrication' clears the heads of pandaren laborers, permanently increasing labor rate by 60% of base.(Up to 3 stacks)(1 sec cooldown)" }
