entries[92743] = { ["name"] = "Krasari Iron", ["text"] = "A Little Patience\nUnique (5)\nUse: Short folk work best with ample iron, increases construction rate by 30% of base for 1 min at dwarf or gnome laborers.(Up to 3 stacks)" }
