entries[92920] = { ["name"] = "Scratched Chromatic Dragonscale", ["text"] = "Binds when picked up\n\"Once priceless, now ruined by squabbling.\"\nSell Price:" }
entries[92921] = { ["name"] = "Eroded Lieutenant's Insignia", ["text"] = "Binds when picked up\n\"Definitely antique, but of questionable usefulness.\"\nSell Price:" }
entries[92922] = { ["name"] = "Stack of Ransom Notes", ["text"] = "Binds when picked up\n\"Each of these seem to be variation on extorting a fellow named Arechron.\"\nSell Price:" }
entries[92923] = { ["name"] = "Pile of Quillboar Tusks", ["text"] = "Binds when picked up\n\"You're not sure how Mankrik convinced someone to take this as collateral.\"\nSell Price:" }
